  $q$Shokz OpenRun Pro 2: open-ear bone conduction sports headphones$q$, $q$Open ears, Bluetooth 5.3, IP55 and up to 12 h of playtime: headphones made for running while staying aware of your surroundings.$q$, '[]'::jsonb, $j$[{"icon": "🦴", "title": "Bone conduction, open ears", "description": "Sound travels through your cheekbones, so your ears stay open to what is around you."}, {"icon": "📶", "title": "Bluetooth 5.3", "description": "Wireless connection to your phone or watch."}, {"icon": "💧", "title": "IP55 protection", "description": "IP55 rating against dust and water splashes."}, {"icon": "🔋", "title": "Up to 12 h of playtime", "description": "About 2 h for a full cable charge."}, {"icon": "🎙️", "title": "Noise-cancelling microphone", "description": "For taking calls during your workouts."}]$j$::jsonb, $j$[{"question": "How long does the battery last?", "answer": "Up to 12 hours of playtime according to the listing; a full charge takes about 2 hours."}, {"question": "What is the protection rating?", "answer": "IP55: protected against dust and water splashes. They are not designed to be submerged."}, {"question": "What is the difference between OpenRun Pro 2 and Mini?", "answer": "The offer includes both versions; the Mini is the smaller-format variant. Choose the version in the offer options."}, {"question": "Which devices do they work with?", "answer": "Any Bluetooth device (phone, watch…). The Shokz app lets you set them up."}, {"question": "How do delivery and returns work?", "answer": "Delivery times, shipping costs, import charges and return conditions are shown on the offer page and may vary: check them before ordering."}, {"question": "How much does it cost?", "answer": "The price shown (£152.06) was recorded at the merchant on 30 October 2026. It changes with offers and coupons: confirm it with the seller before you buy."}]$j$::jsonb, '[]'::jsonb, $q$Shokz OpenRun Pro 2 – bone conduction headphones | Tendpick$q$, $q$Open ears, Bluetooth 5.3, IP55 and up